/* @autogenerated */
import { DestroyRef, inject, Injectable } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Params, Router } from '@angular/router';
import { distinctUntilChanged, map, Observable } from 'rxjs';

/**
 * Estado de pantalla guardado en query params.
 *
 * Se provee a nivel de componente (`providers: [LocalRouteStateService]`): su ciclo de vida es el
 * del componente que lo declara. Al destruirse, limpia de la URL los parámetros que ha enlazado,
 * salvo que la destrucción la provoque una navegación (la URL de destino ya manda).
 */
@Injectable()
export class LocalRouteStateService {
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly destroyRef = inject(DestroyRef);
  private readonly boundKeys = new Set<string>();

  constructor() {
    this.destroyRef.onDestroy(() => this.clear());
  }

  bind(queryParamKeys: string[]): LocalRouteStateBind {
    queryParamKeys.forEach((key) => this.boundKeys.add(key));
    return new LocalRouteStateBind(queryParamKeys, this.router, this.route, this.destroyRef);
  }

  // Limpiar los query params del componente actual
  private clear(): void {
    // Si nos destruye una navegación, no competimos con ella
    if (this.router.currentNavigation() !== null) {
      return;
    }
    const current = this.router.routerState.snapshot.root.queryParams;
    const keys = [...this.boundKeys].filter((key) => key in current);
    if (keys.length === 0) {
      return;
    }
    this.router.navigate([], {
      queryParams: omit(current, keys),
      queryParamsHandling: 'replace', // Mantiene los query params que no estamos limpiando
      replaceUrl: true, // Limpiar no debe dejar una entrada extra en el historial
    });
  }
}

export class LocalRouteStateBind {
  public constructor(
    private readonly queryParamKeys: string[],
    private readonly router: Router,
    private readonly route: ActivatedRoute,
    private readonly destroyRef: DestroyRef,
  ) {}

  go(params: Params): void {
    const current = this.router.routerState.snapshot.root.queryParams;
    this.router.navigate([], {
      queryParams: { ...omit(current, this.queryParamKeys), ...pick(params, this.queryParamKeys) },
      queryParamsHandling: 'replace',
    });
  }

  /** Emite (de forma síncrona al suscribirse) los valores de los parámetros enlazados y sus cambios. */
  watch(): Observable<Params> {
    return this.route.queryParams.pipe(
      map((params) => pick(params, this.queryParamKeys)),
      distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b)),
      takeUntilDestroyed(this.destroyRef),
    );
  }
}

function pick(params: Params, keys: string[]): Params {
  return Object.fromEntries(Object.entries(params).filter(([key]) => keys.includes(key)));
}

function omit(params: Params, keys: string[]): Params {
  return Object.fromEntries(Object.entries(params).filter(([key]) => !keys.includes(key)));
}
